#!/usr/bin/env python3
import base64,os,subprocess
B="/var/www/alburhan"
D={
 "artifacts/alburhan/src/components/layout/AdminLayout.tsx":"",
 "artifacts/alburhan/src/pages/admin/StaffManager.tsx":"",
 "artifacts/alburhan/src/pages/public/StaffVerify.tsx":"",
 "artifacts/alburhan/src/App.tsx":"",
}
for p,b in D.items():
 f=B+"/"+p
 os.makedirs(os.path.dirname(f),exist_ok=True)
 open(f,"wb").write(base64.b64decode(b))
 print("OK:",p.split("/")[-1])
r=subprocess.run(["pnpm","--filter","@workspace/alburhan","run","build"],cwd=B,capture_output=True,text=True)
print("Build","OK" if r.returncode==0 else "FAIL:"+r.stderr[-300:])
subprocess.run(["pm2","restart","api-server"],cwd=B)
print("DONE")
